public class Main {
    int trap(int[] height) {
        int n = height.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            int leftMax = 0, rightMax = 0;
            for (int j = 0; j <= i; j++) leftMax = Math.max(leftMax, height[j]);      // tallest wall to the left
            for (int j = i; j < n; j++) rightMax = Math.max(rightMax, height[j]);      // tallest wall to the right
            total += Math.min(leftMax, rightMax) - height[i];
        }
        return total;
    }

    public static void main(String[] args) {
        int[] height = {4, 2, 0, 3, 2, 5};
        Main solution = new Main();
        System.out.println(solution.trap(height));
    }
}

